import React from 'react';
import BookingForm from './component/BookingForm';

function App() {
  const testSlot = { id: 1, slotNumber: 'A1', hourlyRate: 5 };

  const handleBooked = (booking) => {
    alert(`Booking successful! ID: ${booking.id}`);
  };

  return (
    <div>
      <BookingForm slot={testSlot} onBooked={handleBooked} />
    </div>
  );
}

export default App;
